CREATE SCHEMA IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_americas;
CREATE TABLE IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_americas.iso_nodes (node_id STRING, node_name STRING, iso_id STRING, zone STRING, latitude DECIMAL(9,6), longitude DECIMAL(9,6), is_hub BOOLEAN, hub_name STRING);
CREATE TABLE IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_americas.lmp_realtime (lmp_id BIGINT, node_id STRING, iso_id STRING, interval_datetime TIMESTAMP, lmp DECIMAL(12,4), energy_component DECIMAL(12,4), congestion_component DECIMAL(12,4), loss_component DECIMAL(12,4), data_source STRING);
CREATE TABLE IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_americas.ercot_bess_assets (resource_id STRING, resource_name STRING, qse STRING, county STRING, capacity_mw DECIMAL(10,2), duration_hours DECIMAL(5,2), commissioned_date DATE, rtcb_eligible BOOLEAN);
CREATE TABLE IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_americas.ercot_bess_telemetry (telemetry_id BIGINT, resource_id STRING, recorded_at TIMESTAMP, state_of_charge_pct DECIMAL(5,2), output_mw DECIMAL(10,2), drrs_mw DECIMAL(10,2), reg_up_mw DECIMAL(10,2), reg_down_mw DECIMAL(10,2), tb1_spread DECIMAL(10,4), tb4_spread DECIMAL(10,4), rtcb_signal DECIMAL(10,4), data_source STRING);
CREATE TABLE IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_americas.pjm_capacity_auctions (auction_id STRING, delivery_year STRING, auction_date DATE, clearing_price_mw_day DECIMAL(12,4), total_cost_billions DECIMAL(10,4), data_center_cost_pct DECIMAL(5,2), cleared_capacity_mw DECIMAL(12,2), reliability_shortfall_mw DECIMAL(12,2), price_cap_hit BOOLEAN, data_source STRING);
CREATE TABLE IF NOT EXISTS serverless_sandbox_tladem_catalog.nexus_americas.ieso_nodal_prices (price_id BIGINT, node_id STRING, interval_datetime TIMESTAMP, lmp_cad DECIMAL(12,4), ontario_zonal_price DECIMAL(12,4), basis_spread DECIMAL(12,4), market_type STRING, data_source STRING);
